+      consumedRef.current = true;
+      observer?.disconnect();
+      send("reset");
+    };
+    const enabled = capability.matches && typeof ResizeObserver !== "undefined";
+    enabledRef.current = enabled;
+    setInteractive(enabled);
+    setTravelScale(geometry.width < 850 ? .65 : 1);
